<script setup lang="ts">
import products from '~/data/products.json';
import type { Product } from '~/data/types';

definePageMeta({ layout: false, middleware: 'admin' });
useSeoMeta({ title: 'Painel administrativo | Tecla Nativa', robots: 'noindex, nofollow' });
const adminAuth=useAdminAuth();
const adminAuthorized=computed(()=>Boolean(adminAuth.user.value));
const accountLabel=computed(()=>adminAuth.user.value?.email||'Proprietário da loja');
const accountInitials=computed(()=>{const name=accountLabel.value.split('@')[0]??'';return name.split(/[ ._-]+/).filter(Boolean).slice(0,2).map(part=>part[0]?.toUpperCase()).join('')||'TN'});
async function logout(){await adminAuth.signOut();await navigateTo('/painel/login')}

type Section = 'overview'|'orders'|'finance'|'returns'|'purchasing'|'products'|'variants'|'inventory'|'shipping'|'promotions'|'customers'|'content'|'analytics'|'integrations'|'team'|'activity'|'settings';
type DemoOrder = { id:string; customer:string; initials:string; email:string; phone:string; date:string; total:number; items:{name:string;variant:string;sku:string;qty:number;price:number;image:string}[]; payment:'Pago'|'Pendente'|'Recusado'|'Reembolsado'; status:'Aguardando'|'Em separação'|'Pronto para envio'|'Enviado'|'Entregue'|'Cancelado'; shipping:'Aguardando'|'Etiqueta pendente'|'Em trânsito'|'Entregue'; method:string; carrier:string; tracking:string; address:string; city:string; note:string };
type ProductRow = { id:string; name:string; category:string; price:number; image:string; sku:string; colors:number; variants:number; stock:number; minStock:number; published:boolean; featured:boolean };
const section=ref<Section>('overview');
const sidebarOpen=ref(false);
const searchTerm=ref('');
const orderFilter=ref('Todos os pedidos');
const period=ref('Últimos 7 dias');
const toast=ref('');
const activeOrderId=ref('');
const activeModal=ref<''|'product'|'movement'|'coupon'|'team'>('');
const modalTitle=ref('');
const movementProduct=ref('');
const movementQuantity=ref(1);
const movementType=ref('Entrada');
const productSearch=ref('');
const productCategory=ref('Todas as categorias');
const selectedTab=ref('Todos');
const productPage=ref(1);
let toastTimer: ReturnType<typeof setTimeout> | undefined;

const navigation:{label:string;items:{id:Section;name:string;icon:string;count?:string}[]}[]=[
  {label:'Operação',items:[{id:'overview',name:'Visão geral',icon:'grid'},{id:'orders',name:'Pedidos',icon:'bag',count:'8'},{id:'finance',name:'Financeiro',icon:'chart',count:'2'},{id:'shipping',name:'Expedição',icon:'truck',count:'3'},{id:'returns',name:'Trocas e atendimento',icon:'users',count:'3'},{id:'purchasing',name:'Compras e fornecedores',icon:'box'}]},
  {label:'Catálogo',items:[{id:'products',name:'Produtos',icon:'box'},{id:'variants',name:'Variantes e SKUs',icon:'tag'},{id:'inventory',name:'Estoque',icon:'chart',count:'4'},{id:'promotions',name:'Cupons e ofertas',icon:'tag'},{id:'content',name:'Conteúdo da loja',icon:'page'}]},
  {label:'Relacionamento',items:[{id:'customers',name:'Clientes',icon:'users'}]},
  {label:'Inteligência',items:[{id:'analytics',name:'Análises e relatórios',icon:'chart'}]},
  {label:'Administração',items:[{id:'integrations',name:'Integrações',icon:'plug'},{id:'team',name:'Equipe e permissões',icon:'shield'},{id:'activity',name:'Histórico de atividade',icon:'clock'},{id:'settings',name:'Configurações',icon:'settings'}]},
];
const sectionInfo:Record<Section,{title:string;eyebrow:string;description:string}>={
  overview:{title:'Visão geral',eyebrow:'CENTRAL DE OPERAÇÃO',description:'O que precisa da sua atenção hoje.'},
  orders:{title:'Pedidos',eyebrow:'VENDAS E ATENDIMENTO',description:'Acompanhe pagamento, separação, entrega e histórico de cada pedido.'},
  finance:{title:'Financeiro e conciliação',eyebrow:'PAGAMENTOS E REPASSES',description:'Acompanhe cobranças, taxas, repasses, estornos e divergências por pedido.'},
  returns:{title:'Trocas e atendimento',eyebrow:'PÓS-VENDA E SUPORTE',description:'Organize solicitações de troca, devolução e suporte com pedido vinculado e prazo de resposta.'},
  purchasing:{title:'Compras e fornecedores',eyebrow:'REPOSIÇÃO E ABASTECIMENTO',description:'Planeje pedidos de compra, prazos de entrega e conferência de recebimento.'},
  products:{title:'Produtos',eyebrow:'CATÁLOGO E MERCHANDISING',description:'Gerencie produtos, categorias, imagens, variantes e informações de compatibilidade.'},
  inventory:{title:'Estoque',eyebrow:'CONTROLE DE INVENTÁRIO',description:'Veja disponibilidade por variante e mantenha um histórico de cada movimentação.'},
  variants:{title:'Variantes e SKUs',eyebrow:'CATÁLOGO DETALHADO',description:'Gerencie cada cor e opção com SKU, imagem, preço e estoque próprios.'},
  shipping:{title:'Expedição',eyebrow:'PREPARAÇÃO E ENTREGA',description:'Organize os pedidos pagos desde a separação até a confirmação da entrega.'},
  promotions:{title:'Cupons e ofertas',eyebrow:'PREÇO E CAMPANHAS',description:'Planeje descontos com regras claras, limites e período de validade.'},
  customers:{title:'Clientes',eyebrow:'RELACIONAMENTO',description:'Consulte cadastro e histórico de compras com acesso limitado aos dados necessários.'},
  content:{title:'Conteúdo da loja',eyebrow:'VITRINE E EDITORIAL',description:'Organize destaques, banners, categorias e guias sem alterar o código da loja.'},
  analytics:{title:'Análises e relatórios',eyebrow:'DESEMPENHO DA OPERAÇÃO',description:'Indicadores demonstrativos organizados para apoiar decisões do catálogo e da operação.'},
  integrations:{title:'Integrações',eyebrow:'SERVIÇOS CONECTADOS',description:'Acompanhe o estado e as verificações de cada serviço externo.'},
  team:{title:'Equipe e permissões',eyebrow:'ACESSO ADMINISTRATIVO',description:'Defina acessos por função e reduza a exposição de dados e ações sensíveis.'},
  activity:{title:'Histórico de atividade',eyebrow:'RASTREABILIDADE',description:'Consulte ações administrativas com responsável, horário e alteração registrada.'},
  settings:{title:'Configurações',eyebrow:'PREFERÊNCIAS DA LOJA',description:'Dados comerciais, logística, notificações e preferências da operação.'},
};
const title=computed(()=>sectionInfo[section.value].title);
const desc=computed(()=>sectionInfo[section.value].description);
const catalog=products as Product[];
const productRows=ref<ProductRow[]>(catalog.map((p,index)=>({id:p.id,name:p.name,category:p.categoryLabel,price:p.price,image:p.image,sku:p.sku,colors:p.colors.length,variants:Math.max(1,p.colors.length),stock:[8,3,26,5,42,11,2,17,6,31][index%10]??0,minStock:[5,5,8,5,10,6,5,8,5,8][index%10]??0,published:index<42,featured:!!p.featured})));
const variantRows=computed(()=>catalog.flatMap((product,productIndex)=>product.colors.map((color,colorIndex)=>({id:`${product.id}-${color.id}`,product:product.name,color:color.label,sku:`${product.sku.replace('-ILUSTRATIVO','')}-${color.id.toUpperCase().replaceAll('-','')}`,image:color.image,price:product.price,stock:[8,3,26,5,42,11,2,17,6,31][(productIndex+colorIndex*3)%10]??0,weight:'A revisar',dimensions:'A revisar'}))));
const visibleVariants=computed(()=>variantRows.value.filter(variant=>!searchTerm.value||`${variant.product} ${variant.color} ${variant.sku}`.toLowerCase().includes(searchTerm.value.trim().toLowerCase())));
const categories=['Todas as categorias',...new Set(productRows.value.map(p=>p.category))];
const lowStock=computed(()=>productRows.value.filter(p=>p.stock<=p.minStock));
const orders=ref<DemoOrder[]>([
  {id:'TN-2026-0842',customer:'Marina Costa',initials:'MC',email:'marina.costa@email.com',phone:'(83) 9 8765-4321',date:'Hoje, 14:32',total:648.9,items:[{name:'Teclado compacto 75%',variant:'Grafite · ABNT2',sku:'TN-001-GRA-ABNT',qty:1,price:289,image:'/images/products/teclado-compacto-75.webp'},{name:'Mouse vertical sem fio',variant:'Azul petróleo',sku:'TN-004-AZP',qty:1,price:229.9,image:'/images/products/mouse-vertical-sem-fio.webp'}],payment:'Pago',status:'Aguardando',shipping:'Aguardando',method:'Pix',carrier:'Melhor Envio · Jadlog',tracking:'',address:'Rua das Acácias, 218 · Apto 302',city:'João Pessoa · PB · 58038-120',note:'Entregar na portaria, por favor.'},
  {id:'TN-2026-0841',customer:'Rafael Nunes',initials:'RN',email:'rafael.nunes@email.com',phone:'(11) 9 7654-3210',date:'Hoje, 13:58',total:319.8,items:[{name:'Webcam Full HD com obturador',variant:'Grafite',sku:'TN-015-GRA',qty:1,price:319.8,image:'/images/products/webcam-full-hd-obturador.webp'}],payment:'Pago',status:'Em separação',shipping:'Aguardando',method:'Cartão · 2x',carrier:'Melhor Envio · Correios',tracking:'',address:'Av. Paulista, 1040 · Bloco B',city:'São Paulo · SP · 01310-100',note:''},
  {id:'TN-2026-0840',customer:'Camila Freire',initials:'CF',email:'camila.freire@email.com',phone:'(21) 9 6543-2109',date:'Hoje, 12:21',total:184.5,items:[{name:'Lâmpada inteligente com ajuste de temperatura',variant:'Branca · E27',sku:'TN-031-BRA-E27',qty:2,price:92.25,image:'/images/products/lampada-inteligente-branca.webp'}],payment:'Pago',status:'Pronto para envio',shipping:'Etiqueta pendente',method:'Pix',carrier:'Melhor Envio · Loggi',tracking:'',address:'Rua do Catete, 92',city:'Rio de Janeiro · RJ · 22220-000',note:'Presente. Não incluir preço.'},
  {id:'TN-2026-0839',customer:'Lucas Almeida',initials:'LA',email:'lucas.almeida@email.com',phone:'(31) 9 5432-1098',date:'Hoje, 11:42',total:459,items:[{name:'Headset sem fio para chamadas',variant:'Preto · Bluetooth',sku:'TN-012-PRT-BT',qty:1,price:459,image:'/images/products/headset-sem-fio-chamadas.webp'}],payment:'Pago',status:'Enviado',shipping:'Em trânsito',method:'Cartão · 3x',carrier:'Melhor Envio · Jadlog',tracking:'BR123456789TN',address:'Rua dos Timbiras, 1200 · Sala 8',city:'Belo Horizonte · MG · 30140-061',note:''},
  {id:'TN-2026-0838',customer:'Ana Beatriz Lima',initials:'AB',email:'ana.lima@email.com',phone:'(41) 9 4321-0987',date:'Ontem, 18:05',total:129.9,items:[{name:'Base de carregamento sem fio',variant:'Preto · 15 W',sku:'TN-044-PRT-15W',qty:1,price:129.9,image:'/images/products/base-carregamento-sem-fio.webp'}],payment:'Pendente',status:'Aguardando',shipping:'Aguardando',method:'Pix',carrier:'Melhor Envio · Correios',tracking:'',address:'Alameda Augusto Stellfeld, 412',city:'Curitiba · PR · 80410-140',note:''},
  {id:'TN-2026-0837',customer:'Pedro Henrique',initials:'PH',email:'pedro.h@email.com',phone:'(85) 9 3210-9876',date:'Ontem, 16:44',total:798,items:[{name:'Kit de setup para trabalho remoto',variant:'Kit completo · 4 itens',sku:'TN-049-KIT-04',qty:1,price:798,image:'/images/products/kit-setup-remoto.webp'}],payment:'Pago',status:'Entregue',shipping:'Entregue',method:'Cartão · 4x',carrier:'Melhor Envio · Correios',tracking:'BR009988776TN',address:'Rua José Vilar, 540',city:'Fortaleza · CE · 60125-000',note:''},
  {id:'TN-2026-0836',customer:'Isabela Rocha',initials:'IR',email:'isabela.rocha@email.com',phone:'(27) 9 2109-8765',date:'Ontem, 15:10',total:0,items:[{name:'Switch de rede com oito portas',variant:'Preto · 1 Gbps',sku:'TN-028-PRT-1G',qty:1,price:239,image:'/images/products/switch-oito-portas.webp'}],payment:'Recusado',status:'Cancelado',shipping:'Aguardando',method:'Cartão · recusado',carrier:'—',tracking:'',address:'Av. Nossa Senhora da Penha, 1000',city:'Vitória · ES · 29055-131',note:''},
  {id:'TN-2026-0835',customer:'Bruno Martins',initials:'BM',email:'bruno.martins@email.com',phone:'(19) 9 1098-7654',date:'20 out, 10:17',total:1178.4,items:[{name:'Kit de áudio e iluminação para reuniões',variant:'Preto · kit completo',sku:'TN-050-PRT',qty:1,price:1178.4,image:'/images/products/kit-audio-iluminacao.webp'}],payment:'Pago',status:'Pronto para envio',shipping:'Etiqueta pendente',method:'Pix',carrier:'Melhor Envio · Azul Cargo',tracking:'',address:'Rua Barreto Leme, 1520',city:'Campinas · SP · 13025-085',note:''},
]);
const metrics=[{label:'Receita aprovada',value:'R$ 8.492,60',change:'+12,8%',hint:'vs. período anterior',icon:'chart',color:'var(--a-cyan)'},{label:'Pedidos pagos',value:'24',change:'+8,2%',hint:'de 31 pedidos criados',icon:'bag',color:'var(--a-blue)'},{label:'Ticket médio',value:'R$ 353,86',change:'+3,4%',hint:'sobre pedidos pagos',icon:'tag',color:'var(--a-violet)'},{label:'Ações pendentes',value:'8',change:'3 urgentes',hint:'pedidos + reposição',icon:'spark',color:'var(--a-orange)'}];
const chartValues=[31,43,38,58,47,69,62,82,66,90,78,100,87,115];
const chartPoints=computed(()=>chartValues.map((value,index)=>`${index*30+4},${154-value}`).join(' '));
const chartArea=computed(()=>`4,154 ${chartPoints.value} 394,154`);
const visibleOrders=computed(()=>orders.value.filter(order=>{
  const term=searchTerm.value.trim().toLowerCase();
  const match=!term||`${order.id} ${order.customer} ${order.email} ${order.phone}`.toLowerCase().includes(term);
  const filter=orderFilter.value;
  const statusMatch=filter==='Todos os pedidos'||(filter==='Aguardando pagamento'&&order.payment==='Pendente')||(filter==='A separar'&&['Aguardando','Em separação'].includes(order.status))||(filter==='Em trânsito'&&order.shipping==='Em trânsito')||(filter==='Entregues'&&order.status==='Entregue');
  return match&&statusMatch;
}));
const visibleProducts=computed(()=>productRows.value.filter(product=>{
  const term=productSearch.value.trim().toLowerCase();
  const match=!term||`${product.name} ${product.sku} ${product.category}`.toLowerCase().includes(term);
  return match&&(productCategory.value==='Todas as categorias'||product.category===productCategory.value);
}));
const filteredProducts=computed(()=>visibleProducts.value.filter(product=>selectedTab.value==='Todos'||(selectedTab.value==='Publicados'&&product.published)||(selectedTab.value==='Rascunhos'&&!product.published)||(selectedTab.value==='Com estoque baixo'&&product.stock<=product.minStock)));
const productPageCount=computed(()=>Math.max(1,Math.ceil(filteredProducts.value.length/10)));
const paginatedProducts=computed(()=>filteredProducts.value.slice((productPage.value-1)*10,productPage.value*10));
watch([productSearch,productCategory,selectedTab],()=>{productPage.value=1});
const selectedOrder=computed(()=>orders.value.find(order=>order.id===activeOrderId.value));
const lowStockProducts=computed(()=>productRows.value.filter(product=>product.stock<=product.minStock).slice(0,5));
const orderStatusClass=(status:string)=>status==='Entregue'?'badge-green':status==='Enviado'?'badge-blue':status==='Pronto para envio'?'badge-purple':status==='Em separação'?'badge-orange':status==='Cancelado'?'badge-red':'badge-gray';
const paymentClass=(status:string)=>status==='Pago'?'badge-green':status==='Pendente'?'badge-orange':status==='Reembolsado'?'badge-purple':status==='Recusado'?'badge-red':'badge-gray';
const money=(value:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value);
function notify(message:string){toast.value=message;if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200)}
function selectSection(id:Section){section.value=id;sidebarOpen.value=false;searchTerm.value='';window.scrollTo({top:0,behavior:'smooth'})}
function showOrder(id:string){activeOrderId.value=id}
function closeOrder(){activeOrderId.value=''}
function advanceOrder(){if(!selectedOrder.value)return;const order=orders.value.find(o=>o.id===selectedOrder.value?.id);if(!order)return;if(order.status==='Aguardando')order.status='Em separação';else if(order.status==='Em separação')order.status='Pronto para envio';else if(order.status==='Pronto para envio'){order.status='Enviado';order.shipping='Em trânsito';order.tracking=order.tracking||'BR'+Math.floor(100000000+Math.random()*899999999)+'TN'}else if(order.status==='Enviado'){order.status='Entregue';order.shipping='Entregue'}notify(`Pedido ${order.id} atualizado nesta prévia.`)}
function openModal(kind:typeof activeModal.value,title:string){activeModal.value=kind;modalTitle.value=title}
function saveModal(){if(activeModal.value==='movement'){const product=productRows.value.find(p=>p.id===movementProduct.value);if(product){const amount=Math.max(1,Number(movementQuantity.value)||1);product.stock=Math.max(0,product.stock+(movementType.value==='Saída'?-amount:amount));notify(`Movimentação demonstrativa registrada para ${product.name}.`)}}else if(activeModal.value==='product'){notify('Cadastro de produto demonstrativo salvo apenas nesta tela.')}else if(activeModal.value==='coupon'){notify('Cupom de demonstração criado nesta prévia.')}else if(activeModal.value==='team'){notify('Convite demonstrativo preparado; o envio depende da autenticação.')}activeModal.value=''}
function togglePublish(id:string){const product=productRows.value.find(p=>p.id===id);if(product){product.published=!product.published;notify(`${product.published?'Produto publicado':'Produto ocultado'} nesta prévia.`)}}
function handleEscape(event:KeyboardEvent){if(event.key==='Escape'){closeOrder();activeModal.value='';sidebarOpen.value=false}}
onMounted(()=>window.addEventListener('keydown',handleEscape));
onBeforeUnmount(()=>{window.removeEventListener('keydown',handleEscape);if(toastTimer)clearTimeout(toastTimer)});
</script>

<template>
  <div v-if="adminAuthorized" class="admin-app">
    <a class="skip-link" href="#admin-content">Pular para o conteúdo do painel</a>
    <div v-if="sidebarOpen" class="admin-nav-backdrop" @click="sidebarOpen=false"></div>
    <div class="admin-shell">
      <aside class="admin-sidebar" :class="{'is-open':sidebarOpen}" aria-label="Navegação administrativa">
        <NuxtLink class="admin-brand" to="/" target="_blank" rel="noopener noreferrer" aria-label="Tecla Nativa — abrir a vitrine">
          <span class="admin-brand-mark"><img src="/images/logo-mark.svg" alt="" width="30" height="30"></span>
          <span><strong>tecla nativa</strong><small>console de operação</small></span>
        </NuxtLink>
        <div class="admin-store-pill"><span class="admin-store-avatar"><img src="/images/logo-mark.svg" alt="" width="22" height="22"></span><span class="admin-store-name"><b>Tecla Nativa</b><small>Loja principal</small></span><span aria-hidden="true">⌄</span></div>
        <NuxtLink class="admin-storefront-link" to="/" target="_blank" rel="noopener noreferrer"><span>Abrir vitrine</span><b aria-hidden="true">↗</b></NuxtLink>
        <nav class="admin-nav" aria-label="Seções do painel">
          <section v-for="group in navigation" :key="group.label" class="admin-nav-group">
            <span class="admin-nav-label">{{group.label}}</span>
            <button v-for="item in group.items" :key="item.id" type="button" class="admin-nav-item" :class="{'is-active':section===item.id}" :aria-current="section===item.id?'page':undefined" @click="selectSection(item.id)">
              <span class="admin-nav-icon"><PanelIcon :name="item.icon" :size="17"/></span><span class="admin-nav-name">{{item.name}}</span><span v-if="item.count" class="admin-nav-count">{{item.count}}</span>
            </button>
          </section>
        </nav>
        <div class="admin-sidebar-bottom"><button type="button" class="admin-nav-item" @click="logout"><span class="admin-nav-icon"><PanelIcon name="close" :size="16"/></span><span class="admin-nav-name">Sair do painel</span></button><div class="admin-profile"><span class="admin-profile-avatar">{{accountInitials}}</span><span class="admin-profile-info"><b>{{accountLabel}}</b><small>Proprietário da loja</small></span><button class="admin-profile-menu" aria-label="Abrir configurações do perfil" @click="selectSection('settings')"><PanelIcon name="dots" :size="18"/></button></div></div>
      </aside>

      <main id="admin-content" class="admin-main">
        <header class="admin-topbar">
          <div class="admin-top-left"><button class="admin-mobile-menu" aria-label="Abrir menu do painel" :aria-expanded="sidebarOpen" @click="sidebarOpen=!sidebarOpen"><span aria-hidden="true">☰</span></button><span class="admin-breadcrumb">Console <span aria-hidden="true">/</span> <b>{{title}}</b></span><span class="admin-env"><i></i> PRÉVIA</span></div>
          <div class="admin-top-actions">
            <label class="admin-header-search"><PanelIcon name="search" :size="15"/><input v-model="searchTerm" type="search" aria-label="Buscar nesta seção" placeholder="Buscar nesta seção"><kbd>⌘ K</kbd></label>
            <NuxtLink class="admin-button admin-storefront-toplink" to="/" target="_blank" rel="noopener noreferrer" aria-label="Abrir a vitrine Tecla Nativa em uma nova aba"><span>Abrir vitrine</span><b aria-hidden="true">↗</b></NuxtLink>
            <button class="admin-icon-btn" aria-label="Notificações" @click="notify('Você está em uma prévia: notificações reais serão ligadas no backend.')"><PanelIcon name="bell" :size="16"/></button>
            <button class="admin-icon-btn" aria-label="Abrir configurações" @click="selectSection('settings')"><PanelIcon name="settings" :size="16"/></button>
          </div>
        </header>
        <div class="admin-page-head"><div><span class="admin-page-eyebrow"><i></i>{{sectionInfo[section].eyebrow}}</span><h1>{{title}}</h1><p>{{desc}}</p></div><div class="admin-page-actions"><template v-if="section==='overview'"><label class="sr-only" for="period-select">Período dos indicadores</label><select id="period-select" v-model="period" class="admin-select"><option>Últimos 7 dias</option><option>Últimos 30 dias</option><option>Este mês</option><option>Este trimestre</option></select><button class="admin-button" @click="notify('Relatório demonstrativo preparado para exportação após conectar os dados.')"><PanelIcon name="download" :size="14"/> Exportar</button></template><template v-else-if="section==='products'"><NuxtLink class="admin-button" to="/" target="_blank" rel="noopener noreferrer">Ver vitrine <span aria-hidden="true">↗</span></NuxtLink><button class="admin-button admin-button-primary" @click="openModal('product','Novo produto')"><PanelIcon name="plus" :size="15"/> Novo produto</button></template><template v-else-if="section==='inventory'"><button class="admin-button" @click="selectSection('products')">Ver catálogo</button><button class="admin-button admin-button-primary" @click="openModal('movement','Registrar movimentação')"><PanelIcon name="plus" :size="15"/> Movimentar estoque</button></template><template v-else-if="section==='promotions'"><button class="admin-button admin-button-primary" @click="openModal('coupon','Criar cupom')"><PanelIcon name="plus" :size="15"/> Criar cupom</button></template><template v-else-if="section==='team'"><button class="admin-button admin-button-primary" @click="openModal('team','Convidar pessoa')"><PanelIcon name="plus" :size="15"/> Convidar pessoa</button></template><template v-else-if="section==='orders'"><button class="admin-button" @click="notify('Exportação demonstrativa disponível depois da conexão com o backend.')"><PanelIcon name="download" :size="14"/> Exportar</button></template></div></div>
        <div class="admin-demo-note"><PanelIcon name="spark" :size="15"/><span><strong>Modo de demonstração.</strong> Os dados e ações desta tela são ilustrativos e ficam apenas nesta sessão.</span><span>O front-end está separado do backend.</span></div>

        <template v-if="section==='overview'">
          <section class="admin-stat-grid" aria-label="Indicadores demonstrativos">
            <article v-for="metric in metrics" :key="metric.label" class="admin-stat-card" :style="{'--stat-color':metric.color}"><div class="admin-stat-top"><span>{{metric.label}}</span><span class="admin-stat-icon"><PanelIcon :name="metric.icon" :size="16"/></span></div><div class="admin-stat-value">{{metric.value}}</div><div class="admin-stat-foot"><span class="admin-delta" :class="{warn:metric.label==='Ações pendentes'}">{{metric.change}}</span><span>· {{metric.hint}}</span></div></article>
          </section>
          <div class="admin-grid-2">
            <section class="admin-panel"><div class="admin-panel-head"><div><h2>Receita aprovada</h2><p>Somente pedidos pagos · comparação demonstrativa</p></div><span class="admin-mini-kpi"><i></i><b>R$ 8.492,60</b></span></div><div class="admin-panel-content"><svg class="admin-chart" viewBox="0 0 410 180" role="img" aria-label="Gráfico demonstrativo de receita crescente ao longo dos últimos sete dias"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#4ce2d2" stop-opacity=".25"/><stop offset="100%" stop-color="#4ce2d2" stop-opacity="0"/></linearGradient></defs><line v-for="y in [25,65,105,145]" :key="y" x1="3" :y1="y" x2="405" :y2="y" class="admin-chart-grid"/><polygon :points="chartArea" class="admin-chart-area"/><polyline :points="chartPoints" class="admin-chart-line"/><circle v-for="point in chartPoints.split(' ')" :key="point" :cx="Number(point.split(',')[0])" :cy="Number(point.split(',')[1])" r="2.4" class="admin-chart-dot"/><text x="4" y="174" class="admin-chart-label">14 out</text><text x="112" y="174" class="admin-chart-label">16 out</text><text x="224" y="174" class="admin-chart-label">18 out</text><text x="355" y="174" class="admin-chart-label">20 out</text></svg><div class="admin-chart-legend"><span>Receita <b>R$ 8.492,60</b></span><span class="admin-delta">+12,8% no período</span></div></div></section>
            <section class="admin-panel"><div class="admin-panel-head"><div><h2>Pedidos por etapa</h2><p>Visão rápida do fluxo operacional</p></div><button class="admin-link-button" @click="selectSection('orders')">Ver pedidos →</button></div><div class="admin-panel-content"><div class="admin-pipeline"><div v-for="stage in [{label:'Aguardando ação',count:3,color:'var(--a-orange)',width:'28%'},{label:'Em separação',count:2,color:'var(--a-violet)',width:'20%'},{label:'Pronto para envio',count:2,color:'var(--a-blue)',width:'20%'},{label:'Em trânsito',count:4,color:'var(--a-cyan)',width:'42%'},{label:'Entregues',count:13,color:'var(--a-green)',width:'82%'}]" :key="stage.label" class="admin-pipeline-item"><span>{{stage.label}}</span><span class="admin-pipeline-track"><span class="admin-pipeline-fill" :style="{width:stage.width,'--bar-color':stage.color}"></span></span><b>{{stage.count}}</b></div></div><div class="admin-insight"><span class="admin-insight-icon"><PanelIcon name="spark" :size="15"/></span><div><strong>3 pedidos precisam de atenção</strong><p>Um pagamento ainda está pendente e dois pedidos aguardam separação.</p></div></div></div></section>
          </div>
          <div class="admin-grid-2">
            <section class="admin-panel"><div class="admin-panel-head"><div><h2>Pedidos recentes</h2><p>Mais recentes primeiro · clique para ver o detalhe completo</p></div><button class="admin-link-button" @click="selectSection('orders')">Ver todos →</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Pagamento</th><th>Total</th><th></th></tr></thead><tbody><tr v-for="order in orders.slice(0,5)" :key="order.id" tabindex="0" @click="showOrder(order.id)" @keydown.enter="showOrder(order.id)"><td><strong class="admin-order-id">{{order.id}}</strong></td><td><strong>{{order.customer}}</strong><small>{{order.email}}</small></td><td>{{order.date}}</td><td><span class="admin-badge" :class="paymentClass(order.payment)">{{order.payment}}</span></td><td><strong>{{money(order.total)}}</strong></td><td><button class="admin-icon-btn" :aria-label="`Abrir pedido ${order.id}`" @click.stop="showOrder(order.id)"><PanelIcon name="chevron" :size="15"/></button></td></tr></tbody></table></div></section>
            <section class="admin-panel"><div class="admin-panel-head"><div><h2>Estoque para acompanhar</h2><p>Variantes no limite ou abaixo dele</p></div><button class="admin-link-button" @click="selectSection('inventory')">Abrir estoque →</button></div><div class="admin-panel-content"><div v-if="lowStockProducts.length" class="admin-alert-list"><div v-for="product in lowStockProducts.slice(0,4)" :key="product.id" class="admin-alert-item"><span class="admin-alert-bar"></span><span class="admin-alert-copy"><strong>{{product.name}}</strong><small>{{product.sku}} · mínimo {{product.minStock}} un.</small></span><b class="admin-alert-count">{{product.stock}} un.</b></div></div><div v-else class="admin-empty"><strong>Estoque em dia</strong><p>Nenhum produto está abaixo do limite.</p></div></div></section>
          </div>
          <section class="admin-panel" style="margin-top:13px"><div class="admin-panel-head"><div><h2>Atividade recente</h2><p>Registro demonstrativo de ações importantes</p></div><button class="admin-link-button" @click="selectSection('activity')">Ver histórico →</button></div><div class="admin-panel-content"><div class="admin-feed"><div class="admin-feed-row"><span class="admin-feed-icon"><PanelIcon name="bag" :size="14"/></span><span class="admin-feed-copy"><strong>Novo pedido recebido · TN-2026-0842</strong><small>Pagamento via Pix confirmado na demonstração</small></span><span class="admin-feed-time">há 8 min</span></div><div class="admin-feed-row"><span class="admin-feed-icon"><PanelIcon name="box" :size="14"/></span><span class="admin-feed-copy"><strong>Estoque ajustado · Mouse vertical sem fio</strong><small>Entrada de 6 unidades · Segundo Almeida</small></span><span class="admin-feed-time">há 42 min</span></div></div></div></section>
        </template>

        <template v-else-if="section==='orders'">
          <section class="admin-stat-grid"><article class="admin-stat-card" v-for="stat in [{label:'Todos os pedidos',value:'31',color:'var(--a-blue)'},{label:'Aguardando pagamento',value:'4',color:'var(--a-orange)'},{label:'A separar / enviar',value:'5',color:'var(--a-violet)'},{label:'Entregues no período',value:'13',color:'var(--a-green)'}]" :key="stat.label" :style="{'--stat-color':stat.color}"><div class="admin-stat-top"><span>{{stat.label}}</span><span class="admin-stat-icon"><PanelIcon name="bag" :size="15"/></span></div><div class="admin-stat-value">{{stat.value}}</div><div class="admin-stat-foot">Dados de demonstração</div></article></section>
          <section class="admin-panel" style="margin-top:13px"><div class="admin-toolbar"><label class="admin-toolbar-search"><PanelIcon name="search" :size="14"/><input class="admin-input" v-model="searchTerm" aria-label="Buscar pedido por número ou cliente" placeholder="Pedido, nome, e-mail ou telefone"></label><label class="sr-only" for="order-filter">Filtrar pedidos</label><select id="order-filter" v-model="orderFilter" class="admin-select"><option>Todos os pedidos</option><option>Aguardando pagamento</option><option>A separar</option><option>Em trânsito</option><option>Entregues</option></select><label class="sr-only" for="order-period">Período</label><select id="order-period" class="admin-select"><option>Qualquer período</option><option>Hoje</option><option>Últimos 7 dias</option><option>Últimos 30 dias</option></select><span class="admin-toolbar-spacer"></span><button class="admin-button admin-button-sm" @click="notify('Filtros salvos para esta prévia.')">Salvar filtro</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th><input class="admin-table-check" type="checkbox" aria-label="Selecionar todos os pedidos"></th><th>Pedido</th><th>Cliente</th><th>Data</th><th>Pagamento</th><th>Preparação</th><th>Total</th><th></th></tr></thead><tbody><tr v-for="order in visibleOrders" :key="order.id" tabindex="0" @click="showOrder(order.id)" @keydown.enter="showOrder(order.id)" @keydown.space.prevent="showOrder(order.id)"><td><input class="admin-table-check" type="checkbox" :aria-label="`Selecionar pedido ${order.id}`" @click.stop></td><td><strong class="admin-order-id">{{order.id}}</strong><small>{{order.items.length}} {{order.items.length===1?'item':'itens'}}</small></td><td><strong>{{order.customer}}</strong><small>{{order.email}}</small></td><td>{{order.date}}</td><td><span class="admin-badge" :class="paymentClass(order.payment)">{{order.payment}}</span></td><td><span class="admin-badge" :class="orderStatusClass(order.status)">{{order.status}}</span></td><td><strong>{{money(order.total)}}</strong></td><td><button class="admin-icon-btn" :aria-label="`Ver detalhes do pedido ${order.id}`" @click.stop="showOrder(order.id)"><PanelIcon name="chevron" :size="15"/></button></td></tr><tr v-if="!visibleOrders.length"><td colspan="8"><div class="admin-empty"><strong>Nenhum pedido encontrado</strong><p>Ajuste a busca ou limpe os filtros.</p></div></td></tr></tbody></table></div><div class="admin-pagination"><span>{{visibleOrders.length}} registros nesta prévia · amostra demonstrativa do histórico</span></div></section>
        </template>

        <template v-else-if="section==='products'">
          <section class="admin-stat-grid"><article class="admin-stat-card" v-for="stat in [{label:'Produtos ativos',value:'42',color:'var(--a-cyan)'},{label:'Rascunhos',value:'8',color:'var(--a-violet)'},{label:'Variantes cadastradas',value:'126',color:'var(--a-blue)'},{label:'Precisam de revisão',value:'6',color:'var(--a-orange)'}]" :key="stat.label" :style="{'--stat-color':stat.color}"><div class="admin-stat-top">{{stat.label}}<span class="admin-stat-icon"><PanelIcon name="box" :size="15"/></span></div><div class="admin-stat-value">{{stat.value}}</div><div class="admin-stat-foot">50 produtos-base no catálogo</div></article></section>
          <section class="admin-panel" style="margin-top:13px"><div class="admin-toolbar"><label class="admin-toolbar-search"><PanelIcon name="search" :size="14"/><input class="admin-input" v-model="productSearch" aria-label="Buscar produtos" placeholder="Nome, SKU ou categoria"></label><label class="sr-only" for="product-category">Filtrar categoria</label><select id="product-category" v-model="productCategory" class="admin-select"><option v-for="category in categories" :key="category">{{category}}</option></select><div class="admin-section-tabs"><button v-for="tab in ['Todos','Publicados','Rascunhos','Com estoque baixo']" :key="tab" :class="{active:selectedTab===tab}" @click="selectedTab=tab">{{tab}}</button></div><span class="admin-toolbar-spacer"></span><button class="admin-button admin-button-sm" @click="notify('Importação CSV será conectada na etapa de backend.')">Importar / exportar</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th><input class="admin-table-check" type="checkbox" aria-label="Selecionar todos os produtos"></th><th>Produto</th><th>SKU base</th><th>Categoria</th><th>Variantes</th><th>Preço inicial</th><th>Estoque</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="product in paginatedProducts" :key="product.id"><td><input class="admin-table-check" type="checkbox" :aria-label="`Selecionar ${product.name}`"></td><td><span class="admin-cell-product"><span class="admin-thumb"><img :src="product.image" :alt="''" loading="lazy"></span><span><strong>{{product.name}}</strong><small>{{product.id}} · {{product.featured?'Em destaque':'Catálogo'}}</small></span></span></td><td>{{product.sku}}</td><td>{{product.category}}</td><td>{{product.variants}} cores</td><td><strong>{{money(product.price)}}</strong></td><td><span class="admin-badge" :class="product.stock<=product.minStock?'badge-orange':'badge-green'">{{product.stock}} un.</span></td><td><span class="admin-badge" :class="product.published?'badge-green':'badge-gray'">{{product.published?'Publicado':'Rascunho'}}</span></td><td><div class="admin-inline-actions"><button class="admin-icon-btn" :aria-label="`Editar ${product.name}`" @click="openModal('product',`Editar ${product.name}`)"><PanelIcon name="settings" :size="14"/></button><button class="admin-icon-btn" :aria-label="`${product.published?'Ocultar':'Publicar'} ${product.name}`" @click="togglePublish(product.id)"><PanelIcon :name="product.published?'dots':'plus'" :size="15"/></button></div></td></tr><tr v-if="!filteredProducts.length"><td colspan="9"><div class="admin-empty"><strong>Nenhum produto encontrado</strong><p>Ajuste a busca ou altere os filtros.</p></div></td></tr></tbody></table></div><div class="admin-pagination"><span>{{filteredProducts.length}} produtos · mostrando {{filteredProducts.length?((productPage-1)*10+1):0}}–{{Math.min(productPage*10,filteredProducts.length)}} nesta página</span><span class="admin-pagination-actions"><button :disabled="productPage===1" aria-label="Página anterior" @click="productPage--">‹</button><button v-for="page in productPageCount" :key="page" :class="{current:productPage===page}" :aria-current="productPage===page?'page':undefined" @click="productPage=page">{{page}}</button><button :disabled="productPage===productPageCount" aria-label="Próxima página" @click="productPage++">›</button></span></div></section>
        </template>

        <template v-else-if="section==='inventory'">
          <section class="admin-stat-grid"><article class="admin-stat-card" v-for="stat in [{label:'Unidades disponíveis',value:'684',color:'var(--a-cyan)'},{label:'Variantes em alerta',value:String(lowStock.length),color:'var(--a-orange)'},{label:'Sem estoque',value:'2',color:'var(--a-red)'},{label:'Movimentações no mês',value:'48',color:'var(--a-blue)'}]" :key="stat.label" :style="{'--stat-color':stat.color}"><div class="admin-stat-top">{{stat.label}}<span class="admin-stat-icon"><PanelIcon name="box" :size="15"/></span></div><div class="admin-stat-value">{{stat.value}}</div><div class="admin-stat-foot">Valores demonstrativos por variante</div></article></section>
          <div class="admin-grid-2"><section class="admin-panel"><div class="admin-panel-head"><div><h2>Estoque por produto</h2><p>Consulte disponibilidade e limite de reposição</p></div><button class="admin-link-button" @click="notify('Relatório de estoque exportado nesta prévia.')">Exportar lista ↓</button></div><div class="admin-toolbar"><label class="admin-toolbar-search"><PanelIcon name="search" :size="14"/><input class="admin-input" v-model="productSearch" placeholder="Buscar SKU ou produto" aria-label="Buscar estoque"></label><select class="admin-select" aria-label="Filtrar nível de estoque"><option>Todos os níveis</option><option>Estoque baixo</option><option>Sem estoque</option></select></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Produto / variante</th><th>SKU</th><th>Disponível</th><th>Limite</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="product in productRows.filter(p=>!productSearch||`${p.name} ${p.sku}`.toLowerCase().includes(productSearch.toLowerCase())).slice(0,8)" :key="product.id"><td><span class="admin-cell-product"><span class="admin-thumb"><img :src="product.image" alt="" loading="lazy"></span><span><strong>{{product.name}}</strong><small>Grafite / Marfim / Azul petróleo</small></span></span></td><td>{{product.sku}}</td><td><strong>{{product.stock}} un.</strong></td><td>{{product.minStock}} un.</td><td><span class="admin-badge" :class="product.stock<=product.minStock?'badge-orange':'badge-green'">{{product.stock<=product.minStock?'Repor':'Normal'}}</span></td><td><button class="admin-button admin-button-sm" @click="movementProduct=product.id;openModal('movement','Movimentar '+product.name)">Ajustar</button></td></tr></tbody></table></div></section>
            <section class="admin-panel"><div class="admin-panel-head"><div><h2>Fila de reposição</h2><p>Itens abaixo do estoque mínimo</p></div><span class="admin-badge badge-orange">{{lowStockProducts.length}} alertas</span></div><div class="admin-panel-content"><div class="admin-alert-list"><div v-for="product in lowStockProducts" :key="product.id" class="admin-alert-item"><span class="admin-alert-bar"></span><span class="admin-alert-copy"><strong>{{product.name}}</strong><small>{{product.sku}} · limite mínimo {{product.minStock}}</small></span><b class="admin-alert-count">{{product.stock}}</b></div><div v-if="!lowStockProducts.length" class="admin-empty"><strong>Tudo em ordem</strong><p>Não há itens abaixo do limite.</p></div></div></div></section></div>
          <section class="admin-panel" style="margin-top:13px"><div class="admin-panel-head"><div><h2>Últimas movimentações</h2><p>Registro de demonstração · histórico real será imutável no backend</p></div><button class="admin-link-button" @click="notify('O histórico completo será persistido e auditável no backend.')">Ver histórico completo →</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Movimento</th><th>Produto / SKU</th><th>Quantidade</th><th>Responsável</th><th>Data e hora</th><th>Motivo</th></tr></thead><tbody><tr><td><span class="admin-badge badge-green">Entrada</span></td><td><strong>Mouse vertical sem fio</strong><small>TN-004-ILUSTRATIVO</small></td><td><strong>+ 6 un.</strong></td><td>Segundo Almeida</td><td>Hoje, 13:50</td><td>Reposição de fornecedor</td></tr><tr><td><span class="admin-badge badge-blue">Saída</span></td><td><strong>Teclado compacto 75%</strong><small>TN-001-ILUSTRATIVO</small></td><td><strong>− 2 un.</strong></td><td>Sistema</td><td>Hoje, 12:18</td><td>Pedido pago · TN-2026-0842</td></tr></tbody></table></div></section>
        </template>

        <template v-else-if="section==='shipping'">
          <section class="admin-stat-grid"><article class="admin-stat-card" v-for="stat in [{label:'Aguardando separação',value:'3',color:'var(--a-orange)'},{label:'Prontos para envio',value:'2',color:'var(--a-blue)'},{label:'Em trânsito',value:'4',color:'var(--a-cyan)'},{label:'Exceções de entrega',value:'1',color:'var(--a-red)'}]" :key="stat.label" :style="{'--stat-color':stat.color}"><div class="admin-stat-top">{{stat.label}}<span class="admin-stat-icon"><PanelIcon name="truck" :size="15"/></span></div><div class="admin-stat-value">{{stat.value}}</div><div class="admin-stat-foot">Pedidos demonstrativos</div></article></section>
          <div class="admin-section-tabs" style="padding:12px 0 4px"><button v-for="tab in ['Todos','A separar','Prontos para envio','Em trânsito','Entregues','Com exceção']" :key="tab" :class="{active:selectedTab===tab}" @click="selectedTab=tab">{{tab}}</button></div>
          <section class="admin-panel"><div class="admin-toolbar"><label class="admin-toolbar-search"><PanelIcon name="search" :size="14"/><input class="admin-input" v-model="searchTerm" placeholder="Pedido ou destinatário" aria-label="Buscar envio"></label><select class="admin-select" aria-label="Transportadora"><option>Todas as transportadoras</option><option>Correios</option><option>Jadlog</option><option>Loggi</option></select><button class="admin-button admin-button-sm" @click="notify('O Melhor Envio será conectado no backend; nenhuma etiqueta real foi criada.')">Atualizar rastreios</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Pedido / destinatário</th><th>Itens</th><th>Serviço</th><th>Prazo</th><th>Etapa</th><th>Rastreio</th><th></th></tr></thead><tbody><tr v-for="order in orders.filter(o=>!['Aguardando','Cancelado'].includes(o.status)).filter(o=>!searchTerm||`${o.id} ${o.customer}`.toLowerCase().includes(searchTerm.toLowerCase()))" :key="order.id" @click="showOrder(order.id)"><td><strong class="admin-order-id">{{order.id}}</strong><small>{{order.customer}} · {{order.city.split(' · ')[0]}}</small></td><td>{{order.items.reduce((sum,item)=>sum+item.qty,0)}} un.</td><td>{{order.carrier}}</td><td>3–6 dias úteis</td><td><span class="admin-badge" :class="order.shipping==='Entregue'?'badge-green':'badge-blue'">{{order.shipping}}</span></td><td>{{order.tracking||'Aguardando etiqueta'}}</td><td><button class="admin-button admin-button-sm" @click.stop="showOrder(order.id)">Ver envio</button></td></tr></tbody></table></div></section>
          <section class="admin-panel" style="margin-top:13px"><div class="admin-panel-head"><div><h2>Como a expedição será conectada</h2><p>O desenho do fluxo já contempla conferência e rastreabilidade</p></div><span class="admin-badge badge-purple">Etapa de backend</span></div><div class="admin-panel-content"><div class="admin-pipeline"><div v-for="stage in [{label:'Pagamento confirmado',count:'01',color:'var(--a-green)',width:'100%'},{label:'Separar e conferir itens',count:'02',color:'var(--a-blue)',width:'78%'},{label:'Criar etiqueta no Melhor Envio',count:'03',color:'var(--a-violet)',width:'50%'},{label:'Registrar código de rastreio',count:'04',color:'var(--a-cyan)',width:'28%'}]" :key="stage.label" class="admin-pipeline-item"><span>{{stage.label}}</span><span class="admin-pipeline-track"><span class="admin-pipeline-fill" :style="{width:stage.width,'--bar-color':stage.color}"></span></span><b>{{stage.count}}</b></div></div></div></section>
        </template>

        <template v-else-if="section==='promotions'">
