          <section class="admin-stat-grid"><article class="admin-stat-card" v-for="metric in metrics.slice(0,3).concat([{label:'Conversão da loja',value:'2,8%',change:'+0,4 p.p.',hint:'dados de demonstração',icon:'chart',color:'var(--a-orange)'}])" :key="metric.label" :style="{'--stat-color':metric.color}"><div class="admin-stat-top">{{metric.label}}<span class="admin-stat-icon"><PanelIcon :name="metric.icon" :size="15"/></span></div><div class="admin-stat-value">{{metric.value}}</div><div class="admin-stat-foot"><span class="admin-delta">{{metric.change}}</span> · {{metric.hint}}</div></article></section>
