        <template v-else-if="section==='integrations'">
          <div class="admin-cards-grid"><article v-for="integration in [{name:'Supabase',type:'Banco de dados · autenticação · arquivos',state:'Backend pendente',icon:'box',color:'badge-purple',desc:'Banco de dados, autenticação administrativa, políticas RLS e armazenamento de imagens.'},{name:'PagBank / PagSeguro',type:'Pagamentos',state:'A configurar',icon:'bag',color:'badge-gray',desc:'Checkout, consulta de cobrança, webhook assinado e reconciliação de pedidos.'},{name:'Melhor Envio',type:'Frete · etiquetas · rastreio',state:'A configurar',icon:'truck',color:'badge-gray',desc:'Cotação no servidor, criação de etiqueta após pagamento e sincronização de rastreio.'},{name:'E-mail transacional',type:'Pedidos · suporte · recuperação',state:'Planejado',icon:'page',color:'badge-gray',desc:'Confirmações de pedido, avisos operacionais e recuperação de conta sem revelar existência de e-mail.'},{name:'Analytics da loja',type:'Consentimento · eventos · relatórios',state:'Planejado',icon:'chart',color:'badge-gray',desc:'Eventos necessários para medir jornada e conversão respeitando privacidade.'},{name:'Netlify',type:'Publicação · domínio · deploy',state:'Vitrine publicada',icon:'plug',color:'badge-green',desc:'Hospedagem da vitrine. Ambientes administrativos devem ser protegidos e separados.'}]" :key="integration.name" class="admin-feature-card"><div class="admin-feature-top"><span class="admin-feature-icon"><PanelIcon :name="integration.icon" :size="18"/></span><span class="admin-badge" :class="integration.color">{{integration.state}}</span></div><h3>{{integration.name}}</h3><p>{{integration.type}}</p><p style="margin-top:7px">{{integration.desc}}</p><button class="admin-button admin-button-sm" @click="notify(`${integration.name}: conexão será feita e validada na etapa de backend.`)">Ver requisitos <PanelIcon name="chevron" :size="13"/></button></article></div>
          <section class="admin-panel" style="margin-top:13px"><div class="admin-panel-head"><div><h2>Checklist de conexão segura</h2><p>O front não guarda tokens ou chaves dos serviços</p></div></div><div class="admin-panel-content"><div class="admin-feed"><div class="admin-feed-row"><span class="admin-feed-icon">1</span><span class="admin-feed-copy"><strong>Criar ambiente de desenvolvimento e produção separados</strong><small>Credenciais do ambiente real não entram no pacote do painel.</small></span></div><div class="admin-feed-row"><span class="admin-feed-icon">2</span><span class="admin-feed-copy"><strong>Validar webhooks e assinatura do provedor</strong><small>Retorno visual do checkout não confirma pagamento.</small></span></div><div class="admin-feed-row"><span class="admin-feed-icon">3</span><span class="admin-feed-copy"><strong>Testar idempotência, falhas e reconciliação</strong><small>Um evento repetido não pode duplicar pagamento nem movimentação de estoque.</small></span></div></div></div></section>
        </template>

        <template v-else-if="section==='team'">
          <section class="admin-stat-grid"><article class="admin-stat-card" v-for="stat in [{label:'Pessoas com acesso',value:'4',color:'var(--a-blue)'},{label:'Convites pendentes',value:'1',color:'var(--a-orange)'},{label:'Perfis de acesso',value:'5',color:'var(--a-violet)'},{label:'Última revisão',value:'Hoje',color:'var(--a-green)'}]" :key="stat.label" :style="{'--stat-color':stat.color}"><div class="admin-stat-top">{{stat.label}}<span class="admin-stat-icon"><PanelIcon name="users" :size="15"/></span></div><div class="admin-stat-value">{{stat.value}}</div><div class="admin-stat-foot">Simulação de permissões</div></article></section>
          <section class="admin-panel" style="margin-top:13px"><div class="admin-panel-head"><div><h2>Pessoas e funções</h2><p>Menor privilégio: cada função acessa somente o necessário</p></div><button class="admin-link-button" @click="notify('As permissões serão impostas na API e no RLS, não apenas na interface.')">Como funcionam os acessos ↗</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Pessoa</th><th>Função</th><th>Pedidos</th><th>Catálogo</th><th>Clientes</th><th>Configurações</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="person in [{name:'Segundo Almeida',email:'segundo@teclanativa.com.br',role:'Proprietário',orders:'Editar',catalog:'Editar',customers:'Editar',settings:'Editar',status:'Ativo'},{name:'Bruna Ferreira',email:'bruna@teclanativa.com.br',role:'Catálogo',orders:'Sem acesso',catalog:'Editar',customers:'Sem acesso',settings:'Sem acesso',status:'Ativo'},{name:'Operação de envio',email:'expedicao@teclanativa.com.br',role:'Expedição',orders:'Limitado',catalog:'Leitura',customers:'Limitado',settings:'Sem acesso',status:'Ativo'},{name:'Atendimento',email:'atendimento@teclanativa.com.br',role:'Atendimento',orders:'Limitado',catalog:'Leitura',customers:'Limitado',settings:'Sem acesso',status:'Convite enviado'}]" :key="person.email"><td><strong>{{person.name}}</strong><small>{{person.email}}</small></td><td>{{person.role}}</td><td>{{person.orders}}</td><td>{{person.catalog}}</td><td>{{person.customers}}</td><td>{{person.settings}}</td><td><span class="admin-badge" :class="person.status==='Ativo'?'badge-green':'badge-orange'">{{person.status}}</span></td><td><button class="admin-icon-btn" :aria-label="`Editar acesso de ${person.name}`" @click="notify('A alteração de papel exigirá confirmação e registro de auditoria.')"><PanelIcon name="dots" :size="16"/></button></td></tr></tbody></table></div></section>
          <div class="admin-grid-2 equal"><section class="admin-panel"><div class="admin-panel-head"><div><h2>Perfis previstos</h2><p>Regras a validar no backend antes de habilitar o acesso</p></div></div><div class="admin-panel-content"><div class="admin-feed"><div class="admin-feed-row"><span class="admin-feed-icon"><PanelIcon name="shield" :size="13"/></span><span class="admin-feed-copy"><strong>Proprietário</strong><small>Configuração global e gestão de acessos.</small></span></div><div class="admin-feed-row"><span class="admin-feed-icon"><PanelIcon name="box" :size="13"/></span><span class="admin-feed-copy"><strong>Catálogo</strong><small>Produtos, imagens, categorias e conteúdo.</small></span></div><div class="admin-feed-row"><span class="admin-feed-icon"><PanelIcon name="truck" :size="13"/></span><span class="admin-feed-copy"><strong>Expedição</strong><small>Pedidos pagos, endereço, preparação e rastreio.</small></span></div><div class="admin-feed-row"><span class="admin-feed-icon"><PanelIcon name="users" :size="13"/></span><span class="admin-feed-copy"><strong>Atendimento</strong><small>Consulta limitada, sem acesso a credenciais ou pagamento.</small></span></div></div></div></section><section class="admin-panel"><div class="admin-panel-head"><div><h2>Recomendações de segurança</h2><p>Controle real precisa existir fora da interface</p></div></div><div class="admin-panel-content"><div class="admin-insight"><span class="admin-insight-icon"><PanelIcon name="shield" :size="15"/></span><div><strong>Bloqueio de rota e autorização no servidor</strong><p>Ocultar botões não substitui validação de papel nas APIs e políticas RLS nas tabelas.</p></div></div></div></section></div>
        </template>

        <template v-else-if="section==='activity'">
          <div class="admin-toolbar" style="padding:0 0 12px"><label class="admin-toolbar-search"><PanelIcon name="search" :size="14"/><input v-model="searchTerm" class="admin-input" aria-label="Buscar no histórico de atividade" placeholder="Pessoa, ação ou registro"></label><select class="admin-select" aria-label="Tipo de atividade"><option>Todas as atividades</option><option>Pedidos</option><option>Catálogo</option><option>Estoque</option><option>Acessos</option></select><select class="admin-select" aria-label="Período"><option>Últimos 7 dias</option><option>Hoje</option><option>Últimos 30 dias</option></select></div>
          <section class="admin-panel"><div class="admin-panel-head"><div><h2>Registro administrativo</h2><p>Quem fez o quê, quando e quais valores foram alterados</p></div><span class="admin-badge badge-purple">Auditável no backend</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Data e hora</th><th>Responsável</th><th>Ação</th><th>Registro</th><th>Alteração</th><th>Origem</th></tr></thead><tbody><tr v-for="event in [{at:'Hoje, 14:32:10',person:'Sistema · webhook',action:'Pagamento confirmado',target:'Pedido TN-2026-0842',change:'Pendente → Pago',origin:'PagBank Sandbox'},{at:'Hoje, 13:50:02',person:'Segundo Almeida',action:'Entrada de estoque',target:'Mouse vertical · TN-004',change:'8 → 14 unidades',origin:'Painel'},{at:'Hoje, 12:18:47',person:'Sistema',action:'Reserva de estoque',target:'Teclado 75% · TN-001',change:'10 → 8 unidades',origin:'Pedido TN-2026-0842'},{at:'Hoje, 10:41:13',person:'Bruna Ferreira',action:'Produto atualizado',target:'Headset sem fio',change:'Descrição e imagem',origin:'Painel'},{at:'Ontem, 18:08:22',person:'Segundo Almeida',action:'Cupom ativado',target:'SETUP15',change:'15% · mínimo R$ 250',origin:'Painel'},{at:'Ontem, 15:22:06',person:'Sistema',action:'Rastreio sincronizado',target:'Pedido TN-2026-0839',change:'Código BR123456789TN',origin:'Melhor Envio'}].filter(e=>!searchTerm||`${e.person} ${e.action} ${e.target} ${e.change}`.toLowerCase().includes(searchTerm.toLowerCase()))" :key="event.at"><td>{{event.at}}</td><td><strong>{{event.person}}</strong></td><td>{{event.action}}</td><td>{{event.target}}</td><td>{{event.change}}</td><td><span class="admin-badge badge-gray">{{event.origin}}</span></td></tr></tbody></table></div><div class="admin-pagination"><span>Eventos demonstrativos · valores anteriores não são sobrescritos no registro</span><span class="admin-pagination-actions"><button class="current">1</button><button>2</button><button>3</button><button aria-label="Próxima página">›</button></span></div></section>
        </template>

        <template v-else-if="section==='settings'">
