    <div v-if="activeOrderId" class="admin-overlay" @click.self="closeOrder">
      <section class="admin-drawer" role="dialog" aria-modal="true" aria-labelledby="order-drawer-title" tabindex="-1">
        <div class="admin-drawer-head"><div><h2 id="order-drawer-title">{{selectedOrder?.id}}</h2><p>Detalhe demonstrativo · criado {{selectedOrder?.date}}</p></div><button class="admin-icon-btn" aria-label="Fechar detalhes do pedido" @click="closeOrder"><PanelIcon name="close" :size="16"/></button></div>
        <div v-if="selectedOrder" class="admin-drawer-section"><div style="display:flex;gap:7px;flex-wrap:wrap"><span class="admin-badge" :class="paymentClass(selectedOrder.payment)">{{selectedOrder.payment}}</span><span class="admin-badge" :class="orderStatusClass(selectedOrder.status)">{{selectedOrder.status}}</span><span class="admin-badge badge-gray">{{selectedOrder.shipping}}</span></div></div>
        <div v-if="selectedOrder" class="admin-drawer-section"><h3>Itens comprados · snapshot do pedido</h3><div class="admin-order-lines"><div v-for="item in selectedOrder.items" :key="item.sku" class="admin-order-line"><span class="admin-thumb"><img :src="item.image" alt="" loading="lazy"></span><span><strong>{{item.name}}</strong><small>{{item.variant}} · {{item.sku}} · {{item.qty}} un.</small></span><b>{{money(item.price*item.qty)}}</b></div></div></div>
        <div v-if="selectedOrder" class="admin-detail-grid admin-drawer-section"><div class="admin-detail-block"><h3>Cliente</h3><p>{{selectedOrder.customer}}<br>{{selectedOrder.email}}<br>{{selectedOrder.phone}}</p></div><div class="admin-detail-block"><h3>Entrega</h3><p>{{selectedOrder.address}}<br>{{selectedOrder.city}}</p></div><div class="admin-detail-block"><h3>Pagamento</h3><p>{{selectedOrder.method}}<br>{{selectedOrder.payment}}<br>Total: {{money(selectedOrder.total)}}</p></div><div class="admin-detail-block"><h3>Frete e rastreio</h3><p>{{selectedOrder.carrier}}<br>{{selectedOrder.tracking||'Código ainda não registrado'}}</p></div></div>
        <div v-if="selectedOrder" class="admin-drawer-section"><h3>Observação do pedido</h3><div class="admin-detail-block"><p>{{selectedOrder.note||'Nenhuma observação cadastrada.'}}</p></div></div>
        <div v-if="selectedOrder" class="admin-drawer-section"><h3>Histórico do pedido</h3><div class="admin-timeline"><div class="admin-timeline-row">Pedido criado<small>{{selectedOrder.date}} · dados ilustrativos</small></div><div class="admin-timeline-row">{{selectedOrder.payment==='Pago'?'Pagamento confirmado':'Pagamento '+selectedOrder.payment.toLowerCase()}}<small>Estado apresentado para revisão do painel</small></div><div class="admin-timeline-row">{{selectedOrder.status}}<small>Alterações reais exigirão autorização e auditoria</small></div></div></div>
        <div v-if="selectedOrder" class="admin-drawer-actions"><button class="admin-button admin-button-primary" :disabled="selectedOrder.payment!=='Pago'||['Entregue','Cancelado'].includes(selectedOrder.status)" @click="advanceOrder">Avançar etapa</button><button class="admin-button" @click="notify('Campo de rastreio aparece aqui após conectar o Melhor Envio.')">Atualizar rastreio</button><button class="admin-button admin-button-danger" :disabled="['Cancelado','Entregue'].includes(selectedOrder.status)" @click="notify('Cancelamento requer confirmação e validação no backend.')">Cancelar pedido</button></div>
        <p class="admin-demo-note" style="margin-top:14px">Nenhuma alteração será enviada para cliente ou gateway nesta prévia.</p>
      </section>
    </div>

    <div v-if="activeModal" class="admin-modal-wrap" @click.self="activeModal=''"><section class="admin-modal" role="dialog" aria-modal="true" :aria-labelledby="'modal-title'"><div class="admin-modal-head"><div><h2 id="modal-title">{{modalTitle}}</h2><p>Campos e ações demonstrativos; sem gravação no servidor.</p></div><button class="admin-icon-btn" aria-label="Fechar janela" @click="activeModal=''"><PanelIcon name="close" :size="16"/></button></div>
      <template v-if="activeModal==='movement'"><div class="admin-product-fields"><div class="admin-field full"><label for="movement-product">Produto / variante</label><select id="movement-product" v-model="movementProduct" class="admin-select"><option value="">Selecione o produto</option><option v-for="product in productRows" :key="product.id" :value="product.id">{{product.name}} · {{product.sku}}</option></select></div><div class="admin-field"><label for="movement-kind">Tipo de movimento</label><select id="movement-kind" v-model="movementType" class="admin-select"><option>Entrada</option><option>Saída</option><option>Ajuste</option></select></div><div class="admin-field"><label for="movement-quantity">Quantidade</label><input id="movement-quantity" v-model.number="movementQuantity" class="admin-input" type="number" min="1"></div><div class="admin-field full"><label for="movement-reason">Motivo do movimento</label><select id="movement-reason" class="admin-select"><option>Reposição de fornecedor</option><option>Correção de inventário</option><option>Avaria / perda</option><option>Devolução de cliente</option></select></div><div class="admin-field full"><label for="movement-notes">Observação</label><textarea id="movement-notes" class="admin-textarea" placeholder="Referência da nota, pedido ou justificativa"></textarea></div></div></template>
      <template v-else-if="activeModal==='product'"><div class="admin-product-fields"><div class="admin-field full"><label for="product-title">Nome do produto</label><input id="product-title" class="admin-input" placeholder="Ex.: Teclado compacto 75%"></div><div class="admin-field"><label for="product-sku">SKU base</label><input id="product-sku" class="admin-input" placeholder="TN-051"></div><div class="admin-field"><label for="product-price">Preço inicial</label><input id="product-price" class="admin-input" type="number" min="0" step="0.01" placeholder="0,00"></div><div class="admin-field"><label for="product-category-form">Categoria</label><select id="product-category-form" class="admin-select"><option v-for="category in categories.slice(1)" :key="category">{{category}}</option></select></div><div class="admin-field"><label for="product-status">Status inicial</label><select id="product-status" class="admin-select"><option>Rascunho</option><option>Publicado</option></select></div><div class="admin-field full"><label for="product-description">Descrição</label><textarea id="product-description" class="admin-textarea" placeholder="Benefícios, compatibilidade, limitações e conteúdo da embalagem"></textarea></div><label class="admin-check-row admin-field full"><input type="checkbox">Em destaque na vitrine</label><p class="admin-field full" style="margin:0;color:var(--a-muted);font-size:8px">As variantes terão SKU, preço, estoque, peso e dimensões próprios. A criação completa de produto será implementada com validação no backend.</p></div></template>
      <template v-else-if="activeModal==='coupon'"><div class="admin-product-fields"><div class="admin-field"><label for="coupon-code">Código do cupom</label><input id="coupon-code" class="admin-input" placeholder="EXEMPLO10"></div><div class="admin-field"><label for="coupon-type">Tipo de desconto</label><select id="coupon-type" class="admin-select"><option>Percentual</option><option>Valor fixo</option><option>Frete grátis</option></select></div><div class="admin-field"><label for="coupon-value">Valor do desconto</label><input id="coupon-value" class="admin-input" type="number" min="0" placeholder="10"></div><div class="admin-field"><label for="coupon-minimum">Pedido mínimo</label><input id="coupon-minimum" class="admin-input" type="number" min="0" placeholder="0,00"></div><div class="admin-field"><label for="coupon-start">Início</label><input id="coupon-start" class="admin-input" type="date"></div><div class="admin-field"><label for="coupon-end">Fim</label><input id="coupon-end" class="admin-input" type="date"></div><div class="admin-field"><label for="coupon-total">Limite total de usos</label><input id="coupon-total" class="admin-input" type="number" min="1" placeholder="Sem limite"></div><div class="admin-field"><label for="coupon-customer">Limite por cliente</label><input id="coupon-customer" class="admin-input" type="number" min="1" value="1"></div></div></template>
      <template v-else-if="activeModal==='team'"><div class="admin-product-fields"><div class="admin-field full"><label for="team-email">E-mail para convite</label><input id="team-email" class="admin-input" type="email" placeholder="pessoa@empresa.com.br"></div><div class="admin-field full"><label for="team-role">Função inicial</label><select id="team-role" class="admin-select"><option>Catálogo</option><option>Expedição</option><option>Atendimento</option><option>Administrador</option></select></div><p class="admin-field full" style="margin:0;color:var(--a-muted);font-size:9px">A função define ações e dados que a pessoa poderá acessar. O convite só será enviado depois da configuração segura da autenticação.</p></div></template>
      <div class="admin-modal-actions"><button class="admin-button" @click="activeModal=''">Cancelar</button><button class="admin-button admin-button-primary" @click="saveModal">{{activeModal==='team'?'Preparar convite':activeModal==='movement'?'Registrar movimento':'Salvar nesta prévia'}}</button></div>
    </section></div>
    <div v-if="toast" class="admin-toast" role="status" aria-live="polite">{{toast}}</div>
  </div>
  <main v-else class="admin-app" role="status" aria-live="polite" style="min-height:100vh;display:grid;place-items:center;color:#a6b5c7;background:#080d17">Verificando o acesso seguro…</main>
</template>
